typedef struct {
    RccIrValue value;
    RccIrType type;
    bool is_unsigned;
    bool volatile_access;
    bool atomic_access;
    bool valid;
} RccIrLowerValue;

typedef struct {
    RccIrLowerValue low;
    RccIrLowerValue high;
    bool is_unsigned;
    bool valid;
} RccIrLowerWideValue;

typedef struct RccIrLowerLocal {
    const Decl* declaration;
    RccIrValue address;
    RccIrType type;
    /* Read-only i686 64-bit integers remain as two real i32 SSA values.
     * The address is still materialized for valid address-taking uses, but
     * ordinary reads never need to reload the stack mirror. */
    bool wide_ssa;
    bool wide_ssa_eligible;
    bool wide_ssa_address_escaped;
    /* A mutable pair is kept in SSA until a control-flow merge requires a
     * pair phi.  Canonical while/for loops add explicit low/high loop phis;
     * other loop edges retain the validated stack mirror until modeled. */
    RccIrBlock* wide_ssa_block;
    RccIrLowerWideValue wide_value;
    struct RccIrLowerLocal* next;
} RccIrLowerLocal;

typedef struct RccIrLowerWideState {
    RccIrLowerLocal* local;
    RccIrLowerWideValue value;
    RccIrBlock* block;
    RccIrInstruction* low_phi;
    RccIrInstruction* high_phi;
    struct RccIrLowerWideState* next;
} RccIrLowerWideState;

typedef struct RccIrLowerLabelEdge {
    RccIrBlock* block;
    RccIrLowerWideState* states;
    struct RccIrLowerLabelEdge* next;
} RccIrLowerLabelEdge;

typedef struct RccIrLowerLoopEdge {
    RccIrBlock* block;
    RccIrLowerWideState* states;
    struct RccIrLowerLoopEdge* next;
} RccIrLowerLoopEdge;

typedef struct RccIrLowerLoopFrame {
    RccIrLowerWideState* baseline;
    RccIrLowerLoopEdge* breaks;
    RccIrLowerLoopEdge* continues;
    struct RccIrLowerLoopFrame* previous;
} RccIrLowerLoopFrame;

typedef struct RccIrLowerSwitchLabel {
    const Stmt* statement;
    RccIrBlock* block;
    RccIrBlock* dispatch_block;
    uint64_t case_bits;
    struct RccIrLowerSwitchLabel* next;
} RccIrLowerSwitchLabel;

typedef struct RccIrLowerSwitch {
    const Type* control_type;
    RccIrLowerSwitchLabel* labels;
    RccIrLowerSwitchLabel* labels_tail;
    RccIrLowerSwitchLabel* default_label;
    RccIrLowerWideState* wide_baseline;
    RccIrLowerLoopEdge* wide_breaks;
    RccIrLowerLoopFrame* wide_loop_owner;
    RccIrBlock* scan_block;
    RccIrBlock* no_match_block;
    bool wide_ssa;
    struct RccIrLowerSwitch* previous;
} RccIrLowerSwitch;

typedef struct RccIrLowerLabel {
    const char* name;
    const Stmt* statement;
    RccIrBlock* block;
    size_t goto_count;
    size_t incoming_capacity;
    size_t incoming_count;
    RccIrLowerLabelEdge* incoming;
    RccIrLowerLabelEdge* incoming_tail;
    RccIrLowerWideState* phis;
    struct RccIrLowerLabel* next;
} RccIrLowerLabel;

typedef struct RccIrLowerScopeCleanup {
    const CxxCleanupPlan* plan;
    bool exception_registered;
    struct RccIrLowerScopeCleanup* previous_scope;
    struct RccIrLowerScopeCleanup* allocated_next;
} RccIrLowerScopeCleanup;

typedef struct RccIrLowerVlaDimension {
    const Type* type;
    RccIrValue byte_extent;
    struct RccIrLowerVlaDimension* next;
} RccIrLowerVlaDimension;

typedef struct RccIrLowerVlaAllocation {
    const Decl* declaration;
    RccIrValue stack_pointer;
    RccIrLowerVlaDimension* dimensions;
    bool has_dynamic_storage;
    struct RccIrLowerVlaAllocation* previous_scope;
    struct RccIrLowerVlaAllocation* allocated_next;
} RccIrLowerVlaAllocation;

typedef struct RccIrLowerVlaBoundCapture {
    const Expr* expression;
    RccIrValue address;
    bool typedef_capture;
    struct RccIrLowerVlaBoundCapture* next;
} RccIrLowerVlaBoundCapture;

typedef struct RccIrLowerScratchAllocation {
    struct RccIrLowerScratchAllocation* next;
} RccIrLowerScratchAllocation;

typedef struct {
    RccIrModule* module;
    RccIrFunction* function;
    const Decl* declaration;
    RccIrValue sysv_varargs_gpr_save_area;
    const Type* ast_return_type;
    RccIrBlock* current;
    RccIrLowerLocal* locals;
    RccIrLowerScopeCleanup* scope_cleanups;
    RccIrLowerScopeCleanup* allocated_scope_cleanups;
    RccIrLowerVlaAllocation* vla_allocations;
    RccIrLowerVlaAllocation* allocated_vla_allocations;
    RccIrLowerVlaBoundCapture* vla_bound_captures;
    RccIrLowerScratchAllocation* allocated_scratch;
    RccIrLowerLabel* labels;
    RccIrLowerSwitch* current_switch;
    RccIrBlockId break_target;
    RccIrBlockId continue_target;
    RccIrLowerScopeCleanup* break_cleanup_marker;
    RccIrLowerScopeCleanup* continue_cleanup_marker;
    RccIrLowerVlaAllocation* break_vla_marker;
    RccIrLowerVlaAllocation* continue_vla_marker;
    RccIrLowerLoopFrame* wide_loop;
    const Stmt* current_statement;
    size_t active_debug_inline_call_plus_one;
    RccIrValue aggregate_return_address;
    const Expr* aggregate_result_destination_expression;
    RccIrLowerValue aggregate_result_destination;
    const Decl* conditional_xvalue_owner;
    RccIrValue active_exception_frame;
    RccIrValue wide_phi_zero;
    size_t cxx_array_cleanup_thunk_count;
    /* While a local C++ object is being initialized, successfully completed
     * direct class members are registered individually.  If a later member
     * constructor throws, the active exception frame then destroys only the
     * completed prefix instead of the not-yet-constructed complete object. */
    const Decl* partial_construction_owner;
    /* A reference-bound temporary keeps its cleanup plan on the reference
     * declaration while member addresses are based on its hidden owner. */
    const Decl* partial_construction_cleanup_declaration;
    /* The verified backend handles bound temporary cleanup inside a local
     * C++20 aggregate parenthesized initializer as one full-expression. */
    const Expr* aggregate_paren_initializer;
    int aggregate_return_kind;
    bool allow_nontrivial_temporary_conditional;
    bool capture_typeof_vla_bounds;
    bool terminated;
    bool unsupported;
} RccIrLowerContext;

